import { useState } from 'react';
import {
  Card,
  TextField,
  Select,
  SelectOption,
  Switch,
  Button,
  Alert,
} from '@jinx-ui/react';

const ROLE_OPTIONS: SelectOption[] = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [emailTouched, setEmailTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = EMAIL_PATTERN.test(email);
  const showEmailError = emailTouched && !isEmailValid;

  function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    if (!isEmailValid) {
      setEmailTouched(true);
      return;
    }
    setSubmitted(true);
  }

  return (
    <div className="jx-stack jx-stack-gap-md" style={{ maxWidth: 420 }}>
      {submitted && (
        <Alert
          variant="success"
          title="Приглашение отправлено"
          onClose={() => setSubmitted(false)}
        >
          Приглашение для {email} успешно отправлено.
        </Alert>
      )}

      <Card className="jx-p-lg">
        <form className="jx-stack jx-stack-gap-md" onSubmit={handleSubmit}>
          <TextField
            label="Электронная почта"
            type="email"
            value={email}
            placeholder="name@example.com"
            onChange={(value: string) => setEmail(value)}
            onBlur={() => setEmailTouched(true)}
            error={showEmailError}
            hint={
              showEmailError
                ? 'Введите корректный адрес электронной почты'
                : 'Мы отправим приглашение на этот адрес'
            }
          />

          <Select
            label="Роль"
            value={role}
            options={ROLE_OPTIONS}
            onChange={(value: string) => setRole(value)}
          />

          <Switch
            label="Отправить уведомление"
            checked={notify}
            onChange={(checked: boolean) => setNotify(checked)}
          />

          <Button type="submit" variant="primary" disabled={!isEmailValid}>
            Отправить приглашение
          </Button>
        </form>
      </Card>
    </div>
  );
}

